import{c as t,Z as e,Q as i,j as r,m as l,o as s}from"./chunks/framework.DOi4mjdC.js";const q=JSON.parse('{"title":"念奴娇·赤壁怀古","description":"","frontmatter":{"title":"念奴娇·赤壁怀古","author":"苏轼","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/2.md","filePath":"books/shici/songci/2.md"}'),n={name:"books/shici/songci/2.md"};function h(c,a,p,u,d,_){const o=e("PoemNav");return i(),r("div",null,[a[0]||(a[0]=l('<h1 id="念奴娇·赤壁怀古" tabindex="-1">念奴娇·赤壁怀古 <a class="header-anchor" href="#念奴娇·赤壁怀古" aria-label="Permalink to &quot;念奴娇·赤壁怀古&quot;">​</a></h1><p><strong>[宋] <a href="/authors/sushi.html">苏轼</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>大江东去，浪淘尽，千古风流人物。故垒西边，人道是，三国周郎赤壁。乱石穿空，惊涛拍岸，卷起千堆雪。江山如画，一时多少豪杰。</p><p>遥想公瑾当年，小乔初嫁了，雄姿英发。羽扇纶巾，谈笑间，樯橹灰飞烟灭。故国神游，多情应笑我，早生华发。人生如梦，一尊还酹江月。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>大江：指长江</li><li>故垒：旧时军队营垒的遗迹</li><li>周郎：指周瑜，因其年少有才，人称周郎</li><li>赤壁：赤壁之战的古战场</li><li>公瑾：周瑜的字</li><li>小乔：乔玄的小女儿，周瑜之妻</li><li>纶巾：青丝带头巾，儒将的装束</li><li>樯橹：代指曹操的战船</li><li>酹：以酒洒地，表示祭奠</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>大江之水滚滚东流，滔滔巨浪淘尽了多少千古风流人物。在那旧营垒的西边，人们说那就是三国时周瑜大破曹军的赤壁。陡峭的石壁直插云霄，汹涌的波涛拍打着江岸，激起的浪花像千万堆白雪。江山美丽如画，那个时代涌现了多少英雄豪杰。</p><p>遥想当年的周瑜，小乔刚刚嫁给他，他英姿勃发、神采飞扬。手持羽扇，头戴纶巾，在谈笑之间，曹操的战船便化为灰烬。我神游于当年的古战场，应笑自己太多情，以致过早地生出了白发。人生就像一场梦，还是举起酒杯来祭奠这江上的明月吧。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是苏轼被贬黄州时游赤壁所作，是豪放词的代表作。词人面对壮丽的江山，缅怀古代英雄人物，抒发了自己壮志难酬的感慨。</p><p>上篇写景，开篇&quot;大江东去&quot;气势磅礴，将空间与时间融为一体。&quot;乱石穿空，惊涛拍岸，卷起千堆雪&quot;几句，以雄健的笔力描绘出赤壁的险要地势和壮阔景象，为英雄人物的出场做了铺垫。</p><p>下篇怀古，集中笔墨塑造周瑜的形象。&quot;羽扇纶巾，谈笑间，樯橹灰飞烟灭&quot;，寥寥数语便勾勒出一位风流儒雅的年轻统帅形象，反衬出词人自己仕途坎坷、壮志未酬的失意。结尾&quot;人生如梦，一尊还酹江月&quot;，既有对人生短暂的慨叹，也有旷达超脱的襟怀。</p><p>全词将写景、咏史、抒情融为一体，境界开阔，气势雄浑，是宋词中不可多得的千古名篇。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>苏轼</strong>（1037年－1101年），字子瞻，号东坡居士，北宋著名文学家、书法家、画家，唐宋八大家之一。其词开豪放一派，与辛弃疾并称“苏辛”。</p><p><a href="/authors/sushi.html">查看作者详情 →</a></p></blockquote>',18)),s(o)])}const b=t(n,[["render",h]]);export{q as __pageData,b as default};
